-- ALTER TABLE constraintAction, SET parameter lists and search optimization
-- https://docs.snowflake.com/en/sql-reference/sql/alter-table

ALTER TABLE t DROP CONSTRAINT uq1 CASCADE;

ALTER TABLE t DROP CONSTRAINT uq1 RESTRICT;

ALTER TABLE t DROP FOREIGN KEY (a);

ALTER TABLE t DROP UNIQUE (a, b);

ALTER TABLE t DROP PRIMARY KEY (id) CASCADE;

ALTER TABLE t MODIFY CONSTRAINT c1 NOT ENFORCED;

ALTER TABLE t ALTER CONSTRAINT c1 ENFORCED VALIDATE RELY;

ALTER TABLE t MODIFY PRIMARY KEY (id) NOT ENFORCED NOVALIDATE NORELY;

ALTER TABLE t MODIFY UNIQUE (a, b) ENFORCED;

ALTER TABLE t RENAME CONSTRAINT c1 TO c2;

ALTER TABLE t SET DATA_RETENTION_TIME_IN_DAYS = 30, CHANGE_TRACKING = TRUE;

ALTER TABLE t SET ENABLE_SCHEMA_EVOLUTION = TRUE, COMMENT = 'multiple parameters';

ALTER TABLE t SET CONTACT STEWARD = my_contact;

ALTER TABLE t SET CONTACT STEWARD = my_db.my_schema.my_contact, SUPPORT = support_contact;

ALTER TABLE t ADD SEARCH OPTIMIZATION ON EQUALITY(c1, c2);

ALTER TABLE t ADD SEARCH OPTIMIZATION ON EQUALITY(c1), SUBSTRING(c2);

ALTER TABLE t DROP SEARCH OPTIMIZATION ON EQUALITY(c1);

ALTER TABLE t DROP SEARCH OPTIMIZATION ON c1;

ALTER TABLE t ADD SEARCH OPTIMIZATION;

ALTER TABLE t DROP SEARCH OPTIMIZATION;

ALTER TABLE t MODIFY COLUMN c1 UNSET COMMENT;

ALTER TABLE t ALTER COLUMN c1 UNSET COMMENT;
